/* Herramienta Batch de Consultas Fleet - Paralelo */
let fetch;
try {
    fetch = global.fetch || require('node-fetch');
} catch (e) {
    fetch = global.fetch;
}

const webhookUrl = "http://n8n:5678/webhook/ejecutar-fleet-batch";

let queries;
try {
    queries = typeof $queries === 'string' ? JSON.parse($queries) : $queries;
} catch (e) {
    queries = [$queries];
}

let descriptions;
try {
    descriptions = typeof $descriptions === 'string' ? JSON.parse($descriptions) : ($descriptions || []);
} catch (e) {
    descriptions = [];
}

if (!Array.isArray(queries) || queries.length === 0) {
    return "Error: Se requiere un array de consultas SQL no vacío.";
}

if (queries.length > 4) {
    queries = queries.slice(0, 4);
    descriptions = descriptions.slice(0, 4);
}

const options = {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ queries: queries, descriptions: descriptions })
};

try {
    const response = await fetch(webhookUrl, options);
    if (response.ok) {
        const data = await response.text();
        const safeData = data.length > 12000 ? data.substring(0, 12000) + "... [TRUNCADO]" : data;
        return "Resultado Batch: " + safeData;
    } else {
        const errorText = await response.text();
        return `Error batch: ${response.status} - ${errorText}`;
    }
} catch (error) {
    return `Error conexión: ${error.message}`;
}
